style.css:
@-moz-document domain("youtube.com") {
:root {
    --anime-accent: #d95b2b;
    --anime-cream: #e9dfc9;
    --anime-panel: rgba(20, 18, 16, 0.78);
  }

  html,
  body,
  ytd-app {
    background-color: #171513 !important;
  }

  /* Fixed full-window background using the image you uploaded. */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background-image: url("data:image/jpeg;base64,");
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    opacity: 0.42;
  }

  /* Keep YouTube content above the background; soften large panels. */
  ytd-app,
  #content,
  ytd-page-manager,
  #page-manager,
  ytd-browse,
  ytd-rich-grid-renderer,
  ytd-watch-flexy,
  ytd-search,
  ytd-two-column-browse-results-renderer,
  #primary,
  #secondary {
    position: relative;
    z-index: 1;
    background: transparent !important;
  }

  /* Translucent header and navigation */
  ytd-masthead,
  #guide-content,
  tp-yt-app-drawer,
  ytd-mini-guide-renderer {
    background: rgba(22, 19, 17, 0.88) !important;
    backdrop-filter: blur(12px);
  }

  /* Video cards and text surfaces */
  ytd-rich-item-renderer,
  ytd-compact-video-renderer,
  ytd-video-renderer,
  ytd-playlist-renderer,
  ytd-channel-renderer,
  ytd-reel-item-renderer {
    background: var(--anime-panel) !important;
    border-radius: 12px !important;
    padding: 6px !important;
    backdrop-filter: blur(5px);
  }

  /* Search field */
  #center #search,
  ytd-searchbox {
    background: rgba(35, 30, 26, 0.92) !important;
    border-radius: 24px !important;
  }

  #search-input input,
  input#search {
    color: #f7f0e6 !important;
  }

  /* Warm orange accent for buttons and links */
  ytd-button-renderer a,
  yt-button-shape button,
  #subscribe-button button {
    --yt-spec-call-to-action: var(--anime-accent) !important;
  }

  a:hover,
  yt-formatted-string a {
    color: #ffad7e !important;
  }

  /* Preserve a clean black area around the video player. */
  #movie_player,
  .html5-video-container,
  video.html5-main-video {
    background: #000 !important;
  }

  /* Make text readable over the background. */
  yt-formatted-string,
  #video-title,
  #channel-name,
  #owner-name,
  #text {
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.65);
  }

  /* Optional: hide this image background on very small screens by editing
     the opacity below if you prefer a clearer mobile layout. */
  @media (max-width: 600px) {
    body::before {
      opacity: 0.22;
      background-position: 42% center;
    }
  }
}
